      'Bleicherstrasse 16, 8953 Dietikon ZH': { de: 'Bleicherstrasse 16, 8953 Dietikon ZH', fr: 'Bleicherstrasse 16, 8953 Dietikon ZH', ar: 'Bleicherstrasse 16، 8953 Dietikon ZH' },
      ', Switzerland': { de: ', Schweiz', fr: ', Suisse', ar: '، سويسرا' },
